/* ================= الفترات الضريبية الربع سنوية (وفق شهادة الهيئة) ================= */
const quarterOfYM = ym => {
  const parts = ym.split('-');
  const y = parseInt(parts[0], 10),
    m = parseInt(parts[1], 10);
  return y + '-Q' + (Math.floor((m - 1) / 3) + 1);
};
const quarterMonths = qk => {
  const parts = qk.split('-Q');
  const y = parseInt(parts[0], 10),
    q = parseInt(parts[1], 10);
  const s = (q - 1) * 3 + 1;
  return [0, 1, 2].map(i => y + '-' + String(s + i).padStart(2, '0'));
};
const quarterLabel = qk => {
  const ms = quarterMonths(qk);
  return fmtMonth(ms[0]) + ' — ' + fmtMonth(ms[2]);
};
const quarterDueDate = qk => {
  const parts = qk.split('-Q');
  let y = parseInt(parts[0], 10);
  const q = parseInt(parts[1], 10);
  let m = q * 3 + 1;
  if (m > 12) {
    m -= 12;
    y++;
  }
  return y + '-' + String(m).padStart(2, '0') + '-28';
};
const quarterEndDate = qk => {
  const ms = quarterMonths(qk);
  const parts = ms[2].split('-');
  const y = parseInt(parts[0], 10),
    m = parseInt(parts[1], 10);
  return y + '-' + String(m).padStart(2, '0') + '-' + new Date(y, m, 0).getDate();
};
const listQuarters = () => {
  const cur = quarterOfYM(currentYM());
  const cparts = cur.split('-Q');
  const cy = parseInt(cparts[0], 10),
    cq = parseInt(cparts[1], 10);
  const regQ = quarterOfYM((COMPANY.vatRegDate || '2026-07-01').slice(0, 7));
  const rparts = regQ.split('-Q');
  let y = parseInt(rparts[0], 10),
    q = parseInt(rparts[1], 10);
  const arr = [];
  while (y < cy || y === cy && q <= cq) {
    arr.push(y + '-Q' + q);
    q++;
    if (q > 4) {
      q = 1;
      y++;
    }
  }
  if (arr.length === 0) arr.push(cur);
  return arr;
};

