/* ================= Migration (from old data model) ================= */
function migrateData(parsed) {
  const out = {
    ...parsed
  };
  if (!Object.prototype.hasOwnProperty.call(parsed, 'recurringBills')) out.recurringBills = [];
  if (Array.isArray(parsed.projects)) {
    out.projects = parsed.projects.map((p, idx) => ({
      designFee: p.designFee !== undefined ? p.designFee : p.budget || 0,
      supervisionMonthly: p.supervisionMonthly || 0,
      supervisionMonths: p.supervisionMonths || 0,
      owner: p.owner !== undefined ? p.owner : p.client || '',
      plotNumber: p.plotNumber || '',
      landType: p.landType || (p.grantNumber ? 'منحة' : 'ملك'),
      ownershipNumber: p.ownershipNumber || '',
      projectNo: p.projectNo || 105 + idx,
      emirate: p.emirate || 'الشارقة',
      area: p.area || '',
      projectType: p.projectType || '',
      owningEntity: p.owningEntity || '',
      engineer: p.engineer || '',
      timeline: p.timeline || {},
      approvals: p.approvals || {},
      ...p
    }));
  }
  if (Array.isArray(parsed.invoices) && !Array.isArray(parsed.payments)) {
    out.payments = parsed.invoices.map(i => ({
      id: i.id,
      projectId: i.projectId,
      phase: 'تصميم',
      label: 'فاتورة سابقة رقم ' + (i.number || '—'),
      amount: i.amount,
      date: i.date,
      dueDate: i.dueDate,
      status: i.status,
      _ts: i._ts || 0
    }));
  }
  if (Array.isArray(parsed.expenses) && !Array.isArray(parsed.officeExpenses) && !Array.isArray(parsed.projectCosts)) {
    out.officeExpenses = parsed.expenses.filter(e => !e.projectId).map(e => ({
      ...e,
      category: OFFICE_CATEGORIES.includes(e.category) ? e.category : 'أخرى'
    }));
    out.projectCosts = parsed.expenses.filter(e => e.projectId).map(e => ({
      ...e,
      category: PROJECT_COST_CATEGORIES.includes(e.category) ? e.category : 'أخرى'
    }));
  }
  if (!Array.isArray(out.govFees)) out.govFees = [];
  if (!Array.isArray(out.treasury)) out.treasury = [];
  if (Array.isArray(out.contracts)) out.contracts = out.contracts.map(c => ({
    category: 'خدمات استشارية',
    ...c
  }));
  if (!Array.isArray(out.contracts)) {
    out.contracts = [];
    (out.projects || []).forEach(p => {
      if ((p.designFee || 0) > 0) out.contracts.push({
        id: 'mig-d-' + p.id,
        projectId: p.id,
        type: 'تصميم واعتماد',
        description: 'أتعاب التصميم واعتماد المخططات',
        value: p.designFee,
        date: p.startDate || todayISO(),
        status: p.status === 'منتهٍ' ? 'منتهٍ' : 'سارٍ',
        _ts: 1
      });
      if ((p.supervisionMonthly || 0) > 0) out.contracts.push({
        id: 'mig-s-' + p.id,
        projectId: p.id,
        type: 'إشراف',
        description: 'الإشراف الهندسي الشهري',
        supervisionMonthly: p.supervisionMonthly,
        supervisionMonths: p.supervisionMonths || 0,
        value: (p.supervisionMonthly || 0) * (p.supervisionMonths || 0),
        date: p.startDate || todayISO(),
        status: p.status === 'منتهٍ' ? 'منتهٍ' : 'سارٍ',
        _ts: 2
      });
    });
    if (Array.isArray(out.payments)) {
      out.payments = out.payments.map(pay => {
        if (pay.contractId) return pay;
        if (pay.phase === 'تصميم') return {
          ...pay,
          contractId: 'mig-d-' + pay.projectId
        };
        if (pay.phase === 'إشراف') return {
          ...pay,
          contractId: 'mig-s-' + pay.projectId
        };
        return pay;
      });
    }
  }
  if (!Array.isArray(out.decisions)) out.decisions = [];
  if (!Array.isArray(out.auditLog)) out.auditLog = [];
  if (!Array.isArray(out.staffDir)) out.staffDir = [];
  if (typeof out.fccState !== 'object' || out.fccState === null || Array.isArray(out.fccState)) out.fccState = {};
  out.settings = Object.assign({
    projectsRoot: 'D:\\Projects',
    bankName: '',
    iban: '',
    accountName: ''
  }, out.settings || {});
  out.govFees = out.govFees.map(g => ({
    account: 'البنك',
    ...g
  }));
  if (Array.isArray(out.officeExpenses)) out.officeExpenses = out.officeExpenses.map(e => ({
    account: 'البنك',
    ...e
  }));
  if (Array.isArray(out.projectCosts)) out.projectCosts = out.projectCosts.map(e => ({
    account: 'البنك',
    ...e
  }));
  if (!Array.isArray(out.leaves)) out.leaves = [];
  if (!Array.isArray(out.timesheets)) out.timesheets = [];
  if (!Array.isArray(out.otherIncome)) out.otherIncome = [];
  delete out.invoices;
  delete out.expenses;
  return out;
}

