/* ================= بحث عام داخل الجداول ================= */
function rowSearchText(row, data) {
  let s = Object.values(row).filter(v => typeof v === 'string' || typeof v === 'number').join(' ');
  if (row.projectId) {
    const p = data.projects.find(x => x.id === row.projectId);
    if (p) s += ' ' + (p.projectNo || '') + ' ' + (p.name || '') + ' ' + (p.owner || '') + ' ' + (p.plotNumber || '') + ' ' + (p.ownershipNumber || '') + ' ' + (p.additionalOwners || []).map(o => o.name || '').join(' ');
  }
  if (row.employeeId) {
    const e = data.employees.find(x => x.id === row.employeeId);
    if (e) s += ' ' + (e.name || '');
  }
  if (row.contractId) {
    const c = (data.contracts || []).find(x => x.id === row.contractId);
    if (c) s += ' ' + (c.type || '') + ' ' + (c.description || '');
  }
  return String(s).toLowerCase();
}

