const CLOUD_ENTITIES = ['projects', 'contracts', 'payments', 'govFees', 'officeExpenses', 'projectCosts', 'recurringBills', 'treasury', 'otherIncome', 'employees', 'overtime', 'advances', 'leaves', 'timesheets', 'cars', 'decisions', 'auditLog'];
const ENGINEER_VIEWS = ['projects', 'contracts', 'decisions', 'govFees', 'cars'];
function recordsToData(rows) {
  const d = {
    projects: [],
    contracts: [],
    payments: [],
    govFees: [],
    officeExpenses: [],
    projectCosts: [],
    recurringBills: [],
    treasury: [],
    otherIncome: [],
    employees: [],
    overtime: [],
    advances: [],
    leaves: [],
    timesheets: [],
    cars: [],
    decisions: [],
    auditLog: [],
    staffDir: [],
    attendance: {},
    fccState: {},
    settings: {
      projectsRoot: 'D:\\Projects',
      bankName: '',
      iban: '',
      accountName: ''
    }
  };
  rows.forEach(r => {
    if (r.entity === 'settings') {
      d.settings = {
        ...d.settings,
        ...r.data
      };
      return;
    }
    if (r.entity === 'attendance') {
      if (r.data && r.data.empId) d.attendance[r.data.empId] = r.data.map || {};
      return;
    }
    if (r.entity === 'fccState') {
      d.fccState = r.data && r.data.map || {};
      return;
    }
    if (r.entity === 'staffDir') {
      d.staffDir.push({
        id: r.id,
        ...r.data
      });
      return;
    }
    if (CLOUD_ENTITIES.includes(r.entity)) d[r.entity].push(r.data);
  });
  return d;
}
function dataToRows(data) {
  const rows = [];
  CLOUD_ENTITIES.forEach(entity => {
    (data[entity] || []).forEach(rec => {
      if (rec && rec.id) rows.push({
        id: String(rec.id),
        entity,
        data: rec
      });
    });
  });
  Object.entries(data.attendance || {}).forEach(([empId, map]) => {
    rows.push({
      id: 'att-' + empId,
      entity: 'attendance',
      data: {
        empId,
        map
      }
    });
  });
  (data.employees || []).forEach(e => {
    rows.push({
      id: 'sd-' + e.id,
      entity: 'staffDir',
      data: {
        empId: e.id,
        name: e.name || ''
      }
    });
  });
  rows.push({
    id: 'fccState',
    entity: 'fccState',
    data: {
      map: data.fccState || {}
    }
  });
  rows.push({
    id: 'settings',
    entity: 'settings',
    data: data.settings || {}
  });
  return rows;
}

